        {
            "title": "l",
            "description": "Harum mollitia modi deserunt aut ab provident perspiciatis quo.",
            "dayOfWeek": 4,
            "timeStart": "13:29",
            "timeEnd": "2052-03-13",
            "priority": "high",
            "orderIndex": 39
        }
    ]
};

fetch(url, {
